CREATE DATABASE IF NOT EXISTS vehicle_booking CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vehicle_booking;

CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, department_name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id VARCHAR(20) PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(100) NOT NULL, role ENUM('admin','employee','driver') NOT NULL, department_id INT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (department_id) REFERENCES departments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicle_types (id VARCHAR(20) PRIMARY KEY, type_name VARCHAR(50) NOT NULL, color VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS drivers (id VARCHAR(20) PRIMARY KEY, user_id VARCHAR(20) NULL, phone VARCHAR(20) NOT NULL DEFAULT '', license_no VARCHAR(50) NOT NULL DEFAULT '', FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicles (id VARCHAR(20) PRIMARY KEY, plate_number VARCHAR(50) NOT NULL UNIQUE, vehicle_type_id VARCHAR(20) NOT NULL, status ENUM('available','maintenance','booked') NOT NULL DEFAULT 'available', driver_id VARCHAR(20) NULL, fuel_card_no VARCHAR(50) NOT NULL DEFAULT '', fuel_limit DECIMAL(10,2) NOT NULL DEFAULT 0, fuel_used DECIMAL(10,2) NOT NULL DEFAULT 0, toll_card_no VARCHAR(50) NOT NULL DEFAULT '', toll_limit DECIMAL(10,2) NOT NULL DEFAULT 0, toll_used DECIMAL(10,2) NOT NULL DEFAULT 0, mileage INT NOT NULL DEFAULT 0, FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id), FOREIGN KEY (driver_id) REFERENCES drivers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(20) PRIMARY KEY, user_id VARCHAR(20) NOT NULL, vehicle_id VARCHAR(20) NULL, driver_id VARCHAR(20) NULL, vehicle_type VARCHAR(20) NULL, booking_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, destination TEXT NOT NULL, reason TEXT NOT NULL, job_detail TEXT NOT NULL, passengers INT NOT NULL DEFAULT 1, status ENUM('pending','approved','rejected','completed','cancelled') NOT NULL, approved_by VARCHAR(20) NULL, approved_at DATETIME NULL, reject_reason TEXT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (vehicle_id) REFERENCES vehicles(id), FOREIGN KEY (driver_id) REFERENCES drivers(id), FOREIGN KEY (vehicle_type) REFERENCES vehicle_types(id), FOREIGN KEY (approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS trip_reports (id INT AUTO_INCREMENT PRIMARY KEY, booking_id VARCHAR(20) NOT NULL UNIQUE, odometer_start INT NULL, odometer_end INT NULL, distance_km INT NULL, fuel_cost DECIMAL(10,2) NULL, toll_count INT NULL, toll_cost DECIMAL(10,2) NULL, notes TEXT NULL, receipts JSON NULL, reported_by VARCHAR(20) NULL, completed_at DATETIME NULL, reported_at DATETIME NULL, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (reported_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(20) PRIMARY KEY, user_id VARCHAR(20) NOT NULL, booking_id VARCHAR(20) NULL, notification_type VARCHAR(50) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS expenses (id VARCHAR(20) PRIMARY KEY, vehicle_id VARCHAR(20) NOT NULL, expense_type ENUM('fuel','toll','repair','maintenance','other') NOT NULL, expense_date DATE NOT NULL, amount DECIMAL(10,2) NOT NULL DEFAULT 0, detail TEXT NOT NULL, FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS booking_pool (booking_id VARCHAR(20) NOT NULL, joined_booking_id VARCHAR(20) NOT NULL, PRIMARY KEY (booking_id, joined_booking_id), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (joined_booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;